mapper.delete:
DELETE FROM interview_schedules
WHERE id = #{id}
  AND (user_id = #{userId} OR #{userId} IS NULL)

mapper.select:
SELECT id, user_id as userId, company_name as companyName, position, interview_time::timestamp as interviewTime, interview_type as interviewType, meeting_link as meetingLink, round_number as roundNumber, interviewer, notes, status, created_at::timestamp as createdAt, updated_at::timestamp as updatedAt FROM interview_schedules WHERE (user_id = #{userId} OR #{userId} IS NULL)
AND status = #{status}
AND interview_time >= #{start}
AND interview_time <= #{end}
ORDER BY interview_time ASC

mapper.update:
UPDATE interview_schedules
SET status = #{newStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE status = #{targetStatus}
  AND interview_time < #{now}
